const $g=id=>document.getElementById(id);
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’‘]/g,"'");
const words=s=>norm(s).match(/[a-z0-9œæ]+/g)||[];
const root=w=>{const irregular={cieux:'ciel',yeux:'oeil',chevaux:'cheval',travaux:'travail'};if(irregular[w])return irregular[w];if(w.length>3)w=w.replace(/[sx]$/,'');return w.length>5?w.replace(/(ement|ation|ique|euse|eur|ee|ent|e)$/,''):w;};
