function restoreSearchFilters(){const old=filterMemories.get(searchTab);selectedSources.clear();(old?old.sources:allowedSources()).forEach(v=>selectedSources.add(v));selectedPeriods.clear();(old?old.periods:['1947-1952','1953-1958','1959-1965']).forEach(v=>selectedPeriods.add(v));$g('globalBook').value=searchTab==='brochures'?'-1':old?.book||'-1';selectedParts.clear();(old?.parts||[0,1,2,3]).forEach(x=>selectedParts.add(x));matchKind=old?.matchKind||'phrase';wordForm=old?.wordForm||'exact';sort=old?.sort||'relevance';ascending=old?.ascending||false;updateSort();}
const currentMode=()=>matchKind+(wordForm==='variants'?'-v':'');
function yearPeriod(y){return y<=1952?'1947-1952':y<=1958?'1953-1958':y<=1965?'1959-1965':null;}
function paintGlobalFilters(){search.querySelectorAll('[data-mode]').forEach(b=>{const yes=b.dataset.mode===currentMode();b.classList.toggle('on',yes);b.setAttribute('aria-pressed',String(yes));});search.querySelectorAll('[data-part]').forEach(b=>{const yes=selectedParts.has(+b.dataset.part);b.classList.toggle('on',selectedParts.size!==4&&yes);b.setAttribute('aria-pressed',String(yes));});$g('allParts').classList.toggle('on',selectedParts.size===4);const allowed=allowedSources();const all=allowed.every(x=>selectedSources.has(x));$g('globalBook').closest('.global-strip').hidden=searchTab==='brochures';$g('currentBook').hidden=searchTab!=='bible';search.querySelectorAll('[data-source]').forEach(b=>b.hidden=!allowed.includes(b.dataset.source));$g('sourceAll').classList.toggle('on',all);$g('sourceAll').setAttribute('aria-pressed',String(all));search.querySelectorAll('[data-source]').forEach(b=>{const yes=selectedSources.has(b.dataset.source);b.classList.toggle('on',!all&&yes);b.setAttribute('aria-pressed',String(yes));});const allYears=selectedPeriods.size===3;$g('allPeriods').classList.toggle('on',allYears);$g('allPeriods').setAttribute('aria-pressed',String(allYears));search.querySelectorAll('[data-period]').forEach(b=>{const yes=selectedPeriods.has(b.dataset.period);b.classList.toggle('on',!allYears&&yes);b.setAttribute('aria-pressed',String(yes));b.disabled=!selectedSources.has('VGR')&&!selectedSources.has('SHP');});search.querySelectorAll('[data-match]').forEach(b=>{const yes=b.dataset.match===matchKind;b.classList.toggle('on',yes);b.setAttribute('aria-pressed',String(yes));});search.querySelectorAll('[data-form]').forEach(b=>{const yes=b.dataset.form===wordForm;b.classList.toggle('on',yes);b.setAttribute('aria-pressed',String(yes));});}
function invalidateGlobal(){currentGlobalId++;searchRun++;clearTimeout(globalTimer);if(globalEngine)globalEngine.postMessage({type:'cancel'});globalBusy=false;$g('cancelGlobal').hidden=true;$g('globalStatus').textContent='';lastApplied='';}
function scheduleGlobal(){invalidateGlobal();search.querySelectorAll('[data-count]').forEach(b=>b.textContent='—');if($g('workQ')&&$g('workQ').value.trim()){ $g('globalStatus').textContent='Mise à jour de la recherche…';globalTimer=setTimeout(runSearch,30);}else if(!$g('workQ').value.trim())$g('workResults').innerHTML='<p>Tapez votre recherche.</p>';}
$g('sourceAll').onclick=()=>{selectedParts.clear();[0,1,2,3].forEach(x=>selectedParts.add(x));selectedSources.clear();allowedSources().forEach(x=>selectedSources.add(x));$g('globalBook').value='-1';paintGlobalFilters();scheduleGlobal();};
search.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const v=b.dataset.source;if(selectedSources.size===allowedSources().length){selectedSources.clear();selectedSources.add(v);}else if(selectedSources.has(v)){selectedSources.delete(v);if(!selectedSources.size)allowedSources().forEach(x=>selectedSources.add(x));}else selectedSources.add(v);const book=+$g('globalBook').value;if(book>=0&&!selectedSources.has(book<39?'AT':'NT'))$g('globalBook').value='-1';paintGlobalFilters();scheduleGlobal();});
search.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{const v=b.dataset.period;if(selectedPeriods.size===3){selectedPeriods.clear();selectedPeriods.add(v);}else if(selectedPeriods.has(v)){selectedPeriods.delete(v);if(!selectedPeriods.size)['1947-1952','1953-1958','1959-1965'].forEach(x=>selectedPeriods.add(x));}else selectedPeriods.add(v);paintGlobalFilters();scheduleGlobal();});$g('allPeriods').onclick=()=>{selectedPeriods.clear();['1947-1952','1953-1958','1959-1965'].forEach(x=>selectedPeriods.add(x));paintGlobalFilters();scheduleGlobal();};
$g('currentBook').onclick=()=>{$g('globalBook').value=String(S.book);$g('globalBook').onchange();};
search.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const v=+b.dataset.part;if(selectedParts.size===4){selectedParts.clear();selectedParts.add(v);}else if(selectedParts.has(v)){selectedParts.delete(v);if(!selectedParts.size)[0,1,2,3].forEach(x=>selectedParts.add(x));}else selectedParts.add(v);$g('globalBook').value='-1';paintGlobalFilters();scheduleGlobal();});$g('allParts').onclick=()=>{selectedParts.clear();[0,1,2,3].forEach(x=>selectedParts.add(x));paintGlobalFilters();scheduleGlobal();};
search.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{matchKind=b.dataset.mode.startsWith('phrase')?'phrase':'words';wordForm=b.dataset.mode.endsWith('-v')?'variants':'exact';paintGlobalFilters();scheduleGlobal();});
$g('globalBook').onchange=()=>{const book=+$g('globalBook').value;if(book>=0){selectedParts.clear();[0,1,2,3].forEach(x=>selectedParts.add(x));selectedSources.clear();selectedSources.add(book<39?'AT':'NT');}paintGlobalFilters();scheduleGlobal();};
search.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{matchKind=b.dataset.match;paintGlobalFilters();scheduleGlobal();});search.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{wordForm=b.dataset.form;paintGlobalFilters();scheduleGlobal();});
function fillBookFilter(){if(!D||$g('globalBook').options.length>1)return;$g('globalBook').innerHTML='<option value="-1">Tous les livres de la Bible</option>'+D.books.map((b,i)=>'<option value="'+i+'">'+esc(b[0])+'</option>').join('');}
function updateSort(){for(const [id,key,label] of [['sortDate','date','Année'],['sortRelevance','relevance','Année pertinente']]){$g(id).textContent=label+(sort===key?(ascending?' ↑':' ↓'):' ↕');$g(id).classList.toggle('on',sort===key);$g(id).setAttribute('aria-pressed',String(sort===key));}}
function sortChanged(key){ascending=sort===key?!ascending:key==='date';sort=key;updateSort();if(lastApplied&& !globalBusy){currentGlobalId++;globalEngine.postMessage({type:'page',id:currentGlobalId,page:0,sort,ascending});}else if($g('workQ').value.trim())runSearch();}
$g('sortDate').onclick=()=>sortChanged('date');$g('sortRelevance').onclick=()=>sortChanged('relevance');
window.sortChanged=sortChanged;Object.defineProperty(window,'sort',{get:()=>sort,configurable:true});Object.defineProperty(window,'ascending',{get:()=>ascending,configurable:true});
function makeFallback(){engineMode='compatible';const child={postMessage:m=>setTimeout(()=>handleEngineMessage(m),0),onmessage:null};garageGlobalWorker(child);return {postMessage:m=>setTimeout(()=>child.onmessage({data:m}),0)};}
let readyResolve;
async function ensureGlobalEngine(){if(engineReady)return;if(engineReadyPromise)return engineReadyPromise;engineReadyPromise=new Promise(r=>readyResolve=r);try{const blob=new Blob(['('+garageGlobalWorker.toString()+')()'],{type:'text/javascript'}),url=URL.createObjectURL(blob);globalEngine=new Worker(url);URL.revokeObjectURL(url);globalEngine.onmessage=e=>handleEngineMessage(e.data);globalEngine.onerror=e=>{e.preventDefault();if(!engineReady){globalEngine.terminate();globalEngine=makeFallback();globalEngine.postMessage({type:'init',books:D.books,abbreviations:ABBR});}else{globalBusy=false;$g('cancelGlobal').hidden=true;$g('globalStatus').textContent='Le moteur a été interrompu. Fermez puis rechargez la démo pour réessayer.';}};}catch(e){globalEngine=makeFallback();}globalEngine.postMessage({type:'init',books:D.books,abbreviations:ABBR});return engineReadyPromise;}
async function handleEngineMessage(m){if(m.type==='ready'){engineReady=true;readyResolve();return;}if(m.type==='need-zone'){try{if(INLINE&&INLINE[m.z])globalEngine.postMessage({type:'zone',z:m.z,blob:INLINE[m.z]});else{const response=await fetch('./data/brochures_z'+m.z+'.json.gz?v=3');if(!response.ok)throw Error('Chargement impossible');const buffer=await response.arrayBuffer();globalEngine.postMessage({type:'zone',z:m.z,buffer});}}catch(e){globalEngine.postMessage({type:'zone',z:m.z,error:e.message});}return;}if(m.type==='loaded'){globalLoadedZones.add(m.z);return;}if(m.id!==currentGlobalId)return;if(m.type==='partial'){resultTotal=m.total;resultPage=0;resultPages=m.pages||1;elapsed=m.elapsed;search.querySelectorAll('[data-count]').forEach(b=>b.textContent=m.counts?m.counts[+b.dataset.count]:'—');results=m.items.map(r=>r.type==='msg'?{...r,dg:D.zoff[r.z]+r.i}:r);renderResults();return;}if(m.type==='counts'){search.querySelectorAll('[data-count]').forEach(b=>b.textContent=m.counts[+b.dataset.count]);$g('globalStatus').textContent=m.total+' résultat(s) trouvé(s)…';return;}if(m.type==='progress'){$g('globalStatus').textContent=m.text+' — '+(engineMode==='worker'?'calcul en arrière-plan':'mode compatible');return;}if(m.type==='error'){globalBusy=false;$g('cancelGlobal').hidden=true;$g('globalStatus').textContent='Recherche interrompue : '+m.text;return;}if(m.type==='result'){globalBusy=false;$g('cancelGlobal').hidden=true;resultTotal=m.total;resultPage=m.page;resultPages=m.pages||1;elapsed=m.elapsed;search.querySelectorAll('[data-count]').forEach(b=>b.textContent=m.counts?m.counts[+b.dataset.count]:'—');results=m.items.map(r=>r.type==='msg'?{...r,dg:D.zoff[r.z]+r.i}:r);lastApplied=$g('workQ').value.trim();document.dispatchEvent(new CustomEvent('garage-search-complete',{detail:{q:lastApplied,tab:searchTab,total:m.total}}));$g('globalStatus').textContent=(m.cachedZones?'Résultats réutilisés · ':'')+(engineMode==='worker'?'Calcul en arrière-plan':'Mode compatible');renderResults();}}
async function runSearch(){if(!D)return;clearTimeout(globalTimer);const id=++currentGlobalId,q=$g('workQ').value.trim();if(!q){invalidateGlobal();$g('workResults').innerHTML='<p>Tapez votre recherche.</p>';return;}globalBusy=true;lastApplied='';search.querySelectorAll('[data-count]').forEach(b=>b.textContent='…');$g('cancelGlobal').hidden=false;$g('globalStatus').textContent='Préparation de la recherche…';$g('workResults').innerHTML='<p class="work-note">Recherche en cours… Vous pouvez changer les filtres ou annuler.</p>';await ensureGlobalEngine();if(id!==currentGlobalId)return;const required=new Set();D.meta.forEach(m=>{const y=1900+(+m[0].slice(0,2));if(selectedPeriods.has(yearPeriod(y))&&selectedSources.has(m[2]==='VGR'?'VGR':'SHP'))required.add(m[4]);});globalEngine.postMessage({type:'search',id,q,mode:currentMode(),sources:[...selectedSources],periods:[...selectedPeriods],book:+$g('globalBook').value,parts:searchTab==='bible'?[...selectedParts]:[0,1,2,3],zones:[...required].sort().filter(available),sort,ascending});}
window.GaragePrewarm=async function(){await ensureGlobalEngine();globalEngine.postMessage({type:'prewarm',zones:[1,2,3,4,5].filter(available)});};
function requestGlobalPage(page){if(!lastApplied||globalBusy)return;currentGlobalId++;globalEngine.postMessage({type:'page',id:currentGlobalId,page,sort,ascending});$g('workResults').scrollIntoView({block:'start'});}
$g('cancelGlobal').onclick=()=>{invalidateGlobal();$g('globalStatus').textContent='Recherche annulée.';$g('workResults').innerHTML='<p>Recherche annulée. Vous pouvez modifier les filtres.</p>';};
$g('workGo').textContent='→';$g('workGo').setAttribute('aria-label','Lancer la recherche');$g('workGo').onclick=runSearch;$g('workQ').onkeydown=e=>{if(e.key==='Enter')runSearch();};$g('workQ').oninput=scheduleGlobal;
const globalStyle=document.createElement('style');globalStyle.textContent=`#workSearch[data-mode=bible] #workCorpora{flex-wrap:wrap;overflow:visible}#workSearch[data-mode=bible] #bookFilter{margin:0;flex:1;min-width:190px}#workSearch[data-mode=brochures] .native-code{background:var(--ink);color:white;border-radius:99px;padding:4px 9px}#workSearch[data-mode=brochures] .native-title{font:700 17px Georgia,serif}#workSearch[data-mode=brochures] .native-bh{align-items:flex-start}.brochure-count{margin-left:auto;background:#fff2b5;border-radius:99px;padding:4px 8px;white-space:nowrap;font-size:11px;font-weight:800;color:#705a14}#workSearch[data-mode=brochures] #workCorpora button{font-size:12px;padding:8px 12px}#workQueryRow{background:white;border:1px solid var(--line);border-radius:24px;padding:5px;gap:0}#workQueryRow:before{content:'🔍';padding:0 8px;font-size:18px}#workQueryRow .work-input{border:0;background:transparent;font-size:16px;padding:10px 4px}#workGo{background:var(--ink);color:white;border:0;border-radius:50%;width:40px;height:40px;padding:0;font-size:21px}.global-strip{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:12px 0}.global-strip button{background:#fff;border:1px solid #e8e0d6;border-radius:99px;padding:8px 12px;font:700 12px system-ui;cursor:pointer;color:#5c5650}.global-strip button.on{background:#1a1c1e;color:white;border-color:#1a1c1e}.global-strip button:disabled{opacity:.35;cursor:default}.filter-label{font:700 11px system-ui;color:#8a8076}.global-strip select{background:white;flex:1;min-width:150px;border:1px solid #e8e0d6;border-radius:18px!important}#workCorpora{flex-wrap:nowrap;gap:4px;overflow-x:auto;padding:3px 0}#workCorpora button{white-space:nowrap;font-size:10.5px;padding:8px 7px;flex-shrink:0}#globalStatus{min-height:18px}#cancelGlobal{border:1px solid #ddd;border-radius:16px;padding:7px;background:white}.global-year{font:800 13px system-ui;color:#8a6a3a;margin:18px 0 9px}#workResults .native-card,#workResults .vcard{content-visibility:auto;contain-intrinsic-size:300px}#workResults{scroll-margin-top:175px;overflow-anchor:none}#workResults .native-card,#workResults .vcard{contain:layout paint style;content-visibility:auto;contain-intrinsic-size:auto 230px}#workSearch{-webkit-overflow-scrolling:touch;overscroll-behavior:contain}.global-pages{display:flex;align-items:center;justify-content:center;gap:12px;margin:20px 0}.global-pages button{padding:10px;border-radius:18px;border:1px solid #ddd;background:white;cursor:pointer}`;document.head.append(globalStyle);paintGlobalFilters();updateSort();
function dateOf(code){const m=code.match(/^(\d{2})-(\d{2})(\d{2})/);return m&&+m[2]>0&&+m[3]>0?'19'+m[1]+'-'+m[2]+'-'+m[3]:null;}
function resultHighlightRanges(text,q){const query=String(q||'').trim();if(!query)return[];const variant=wordForm==='variants',terms=words(query),ranges=[];if(!terms.length)return ranges;if(matchKind==='phrase'&&!variant){let folded='',starts=[],ends=[],offset=0;for(const ch of text){const part=norm(ch);for(let i=0;i<part.length;i++){folded+=part[i];starts.push(offset);ends.push(offset+ch.length)}offset+=ch.length}const needle=norm(query);if(!needle)return ranges;let at=folded.indexOf(needle);while(at>=0){const before=folded[at-1]||' ',after=folded[at+needle.length]||' ';if(!/[a-z0-9œæ]/.test(before)&&!/[a-z0-9œæ]/.test(after))ranges.push([starts[at],ends[at+needle.length-1]]);at=folded.indexOf(needle,at+1)}}else{const tokens=[];for(const m of text.matchAll(/[\p{L}\p{N}]+/gu)){const w=words(m[0])[0];if(w)tokens.push({w:variant?root(w):w,start:m.index,end:m.index+m[0].length})}const qwords=terms.map(w=>variant?root(w):w);if(matchKind==='phrase'){for(let i=0;i+qwords.length<=tokens.length;i++)if(qwords.every((w,j)=>tokens[i+j].w===w))ranges.push([tokens[i].start,tokens[i+qwords.length-1].end])}else{const wanted=new Set(qwords);for(const t of tokens)if(wanted.has(t.w))ranges.push([t.start,t.end])}}ranges.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const merged=[];for(const r of ranges){const last=merged[merged.length-1];if(last&&r[0]<=last[1])last[1]=Math.max(last[1],r[1]);else merged.push(r)}return merged;} function resultSnippet(text){const q=$g('workQ').value.trim(),ranges=resultHighlightRanges(text,q),first=ranges[0],start=first?Math.max(0,first[0]-90):0,end=Math.min(text.length,Math.max(start+440,first?first[1]+90:start+440));let out='',cursor=start;for(const [a,b] of ranges){if(b<=start||a>=end)continue;const lo=Math.max(start,a),hi=Math.min(end,b);if(lo<cursor)continue;out+=esc(text.slice(cursor,lo))+'<mark>'+esc(text.slice(lo,hi))+'</mark>';cursor=hi}out+=esc(text.slice(cursor,end));return (start?'… ':'')+out+(end<text.length?' …':'');}
function crossReferences(r){if(searchTab!=='advanced')return '';const links=r.type==='bible'?linksOfVi(viOf(r.b,r.c,r.v)):linksOfPara(r.dg,r.n);if(!links.length)return '';return '<div class="native-cross"><div class="native-cross-title">'+(r.type==='bible'?'Passages correspondants dans les brochures':'Références bibliques correspondantes')+'</div>'+links.slice(0,12).map(li=>{const l=D.links[li],label=r.type==='bible'?`${D.meta[l[0]][0]} · ${D.meta[l[0]][2]==='VGR'?'VGR':'Shekinah'} · § ${l[1]}`:vref(l[2]);return `<button class="work-ref c${l[3]}" style="border-bottom:3px solid var(--c${l[3]})" data-cross="${li}" data-kind="${r.type}">${esc(label)} · ${CAT[l[3]]}</button>`;}).join('')+(links.length>12?`<span class="work-note">+ ${links.length-12} liens dans la lecture.</span>`:'')+'</div>';}
function renderResults(){let html=`<p class="work-note">${globalBusy?'Résultats provisoires · ':''}${Number(resultTotal||0).toLocaleString('fr')} résultat(s) trouvé(s) · ${Math.min(results.length,shown).toLocaleString('fr')} résultat(s) affiché(s) sur cette page · page ${resultPage+1}/${resultPages}${globalBusy?' · calcul en cours':''}. ${sort==='date'?'Brochures regroupées par année ; versets bibliques ensuite.':''}</p>`;if(!results.length)html+='<p>Aucun résultat. Essayez Tous les mots ou les variantes.</p>';
 const groups=[],byDoc=new Map();results.slice(0,shown).forEach((r,i)=>{if(r.type==='bible')groups.push({type:'bible',items:[[r,i]]});else{if(!byDoc.has(r.dg)){const g={type:'msg',dg:r.dg,items:[]};byDoc.set(r.dg,g);groups.push(g);}byDoc.get(r.dg).items.push([r,i]);}});
 let previousYear=null;html+=groups.map(g=>{if(g.type==='bible'){const [r,i]=g.items[0];return `<article class="vcard shadow"><div class="vh"><span class="vref">${esc(r.title)}</span><button class="native-open" data-result="${i}">Lire →</button></div><p class="vt"><span class="num">${r.v}</span>${esc(r.text)}</p>${crossReferences(r)}</article>`;}
 const m=D.meta[g.dg],first=g.items[0],year=1900+(+m[0].slice(0,2)),period=yearPeriod(year);let heading='';if(sort==='date'&&previousYear!==year){heading='<div class="global-year">'+year+' · '+(period||'Date non classée')+'</div>';previousYear=year;}return heading+`<article class="native-card"><button class="native-bh" data-result="${first[1]}"><span class="native-code">${m[0]}</span><span><span class="native-title">${esc(m[1])}</span><span class="native-sub" style="display:block">${m[3]} · ${m[2]==='VGR'?'VGR':'Shekinah'} · ${period||year} · ${g.items.length} § affiché(s)</span></span>${searchTab==='brochures'?'<span class="brochure-count" title="Paragraphes affichés sur cette page">'+g.items.length+' §</span>':''}</button>`+(()=>{const sn=([r,i])=>`<button class="native-sn" data-result="${i}"><span class="native-pn">§ ${r.n}</span>${resultSnippet(r.text)}</button>${crossReferences(r)}`;const rest=g.items.slice(1);return sn(g.items[0])+(rest.length?`<button class="native-acc" type="button" aria-expanded="false"><span class="acc-caret">▸</span> ${rest.length} autre${rest.length>1?'s':''} paragraphe${rest.length>1?'s':''} rattaché${rest.length>1?'s':''}</button><div class="native-more" hidden>${rest.map(sn).join('')}</div>`:'');})()+'</article>';}).join('');
 if(resultPages>1)html+='<div class="global-pages"><button id="globalPrev" '+(resultPage===0?'disabled':'')+'>← Précédent</button><span>'+(resultPage+1)+' / '+resultPages+'</span><button id="globalNext" '+(resultPage+1>=resultPages?'disabled':'')+'>Suivant →</button></div>';$g('workResults').innerHTML=html;
 $g('workResults').querySelectorAll('.native-acc').forEach(b=>b.onclick=()=>{const more=b.nextElementSibling,open=more.hidden;more.hidden=!open;b.setAttribute('aria-expanded',String(open));b.querySelector('.acc-caret').textContent=open?'▾':'▸';});
 $g('workResults').querySelectorAll('[data-result]').forEach(b=>b.onclick=async()=>{const r=results[+b.dataset.result];search.hidden=true;if(r.type==='bible')goBible(r.b,r.c,r.v);else await openBrochure(r.dg,r.n,null);});
 $g('workResults').querySelectorAll('[data-cross]').forEach(b=>b.onclick=async()=>{const l=D.links[+b.dataset.cross];search.hidden=true;if(b.dataset.kind==='bible')await openBrochure(l[0],l[1],l[2]);else goBible(VB[l[2]],VC[l[2]],VV[l[2]]);});if($g('globalPrev'))$g('globalPrev').onclick=()=>requestGlobalPage(resultPage-1);if($g('globalNext'))$g('globalNext').onclick=()=>requestGlobalPage(resultPage+1);}
let searchTouch=null;
search.addEventListener('touchstart',e=>{if(e.touches.length!==1||e.target.closest('input,select,textarea,button')){searchTouch=null;return;}const t=e.touches[0];searchTouch={x:t.clientX,y:t.clientY,t:Date.now()};},{passive:true});
search.addEventListener('touchend',e=>{const p=searchTouch;searchTouch=null;if(!p||!e.changedTouches.length||String(getSelection()))return;const t=e.changedTouches[0],dx=t.clientX-p.x,dy=t.clientY-p.y;if(Date.now()-p.t>900||Math.abs(dx)<80||Math.abs(dx)<Math.abs(dy)*1.7)return;const tabs=['brochures','bible','advanced'],i=tabs.indexOf(searchTab)+(dx<0?1:-1);if(i>=0&&i<3)search.querySelector('[data-st="'+tabs[i]+'"]').click();},{passive:true});
// Annotations : identifiant de passage + offsets textuels, distincts des couleurs d’analyse.
let notes=[],persistent=true;const KEY='garage-annotations-v1';try{notes=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(notes))notes=[];}catch(e){persistent=false;notes=[];}
function saveNotes(){try{localStorage.setItem(KEY,JSON.stringify(notes));}catch(e){persistent=false;}updateStorageLabel();}
function updateStorageLabel(){if($g('annoStorage'))$g('annoStorage').textContent=persistent?'Marquages enregistrés dans ce navigateur. Exportez une copie pour les conserver.':'Stockage bloqué dans cet aperçu : marquages temporaires. Exportez-les avant de fermer.';}
function keyFor(p){const card=p.closest('.vcard,.pcard');if(!card)return null;return p.classList.contains('vt')?`b:${S.book}:${S.chap}:${card.id.slice(2)}`:`m:${S.doc}:${card.id.slice(2)}`;}
function textNodes(p){const w=document.createTreeWalker(p,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('.num')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let n,a=[];while(n=w.nextNode())a.push(n);return a;}
function plainText(p){return textNodes(p).map(n=>n.textContent).join('');}
let selected=null,color='#ffe066';
const toolbar=document.createElement('div');toolbar.id='annoToolbar';toolbar.className='anno-toolbar';toolbar.hidden=true;toolbar.innerHTML=`<div class="work-row"><b>Marquage personnel</b><button id="annoClose" style="margin-left:auto">✕</button></div><div class="work-row" style="margin:10px 0">${['#ffe066','#9de2b5','#a8ceff','#f4a9c6'].map(c=>`<button class="swatch" data-ink="${c}" style="background:${c}" aria-label="Choisir ${c}"></button>`).join('')}<label title="Couleur personnalisée"><input id="annoCustom" type="color" value="#ffe066" aria-label="Couleur personnalisée"></label></div><div class="work-row"><button id="annoHighlight">Surligner</button><button id="annoUnderline">Souligner</button><button id="annoErase">Effacer la sélection</button><button id="annoExport">Exporter</button><button id="annoImport">Importer</button></div><input id="annoFile" type="file" accept="application/json" hidden><p class="work-note" id="annoStorage"></p><small id="annoFeedback">Sélectionnez quelques mots dans un seul paragraphe ou verset.</small>`;document.body.append(toolbar);updateStorageLabel();
function chooseColor(c){color=c;toolbar.querySelectorAll('[data-ink]').forEach(b=>b.classList.toggle('picked',b.dataset.ink===c));$g('annoCustom').value=c;}
toolbar.querySelectorAll('[data-ink]').forEach(b=>{b.onpointerdown=e=>e.preventDefault();b.onclick=()=>chooseColor(b.dataset.ink);});$g('annoCustom').oninput=e=>chooseColor(e.target.value);chooseColor(color);
$g('annoClose').onclick=()=>{toolbar.hidden=true;selected=null;getSelection()?.removeAllRanges();};
function captureSelection(){if(window.WMBMarks?.active)return;const sel=getSelection();if(!sel||sel.isCollapsed||!sel.rangeCount)return;const range=sel.getRangeAt(0),sp=(range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement).closest('.vt,.pt'),ep=(range.endContainer.nodeType===1?range.endContainer:range.endContainer.parentElement).closest('.vt,.pt');if(!sp||sp!==ep||!sp.closest('#bibleView,#msgView'))return;const nodes=textNodes(sp);let at=0,start=null,end=null;for(const n of nodes){if(n===range.startContainer)start=at+range.startOffset;if(n===range.endContainer)end=at+range.endOffset;at+=n.length;}if(start===null||end===null||end<=start)return;selected={key:keyFor(sp),start,end,text:plainText(sp),p:sp};toolbar.hidden=false;$g('annoFeedback').textContent='« '+selected.text.slice(start,end).slice(0,75)+' »';}
document.addEventListener('selectionchange',()=>{clearTimeout(window._selectionTimer);window._selectionTimer=setTimeout(captureSelection,140);});
function applyNote(type){if(!selected){$g('annoFeedback').textContent='Sélectionnez d’abord les mots à marquer.';return;}notes.push({id:Date.now()+'-'+Math.random().toString(36).slice(2),key:selected.key,start:selected.start,end:selected.end,text:selected.text,type,color});saveNotes();paintAnnotations();getSelection()?.removeAllRanges();$g('annoFeedback').textContent=type==='highlight'?'Surlignage ajouté.':'Soulignement ajouté.';}
for(const id of ['annoHighlight','annoUnderline','annoErase'])$g(id).onpointerdown=e=>e.preventDefault();
$g('annoHighlight').onclick=()=>applyNote('highlight');$g('annoUnderline').onclick=()=>applyNote('underline');
$g('annoErase').onclick=()=>{if(!selected){$g('annoFeedback').textContent='Sélectionnez les mots dont vous souhaitez effacer le marquage.';return;}const next=[];for(const n of notes){if(n.key!==selected.key||n.end<=selected.start||n.start>=selected.end){next.push(n);continue;}if(n.start<selected.start)next.push({...n,end:selected.start});if(n.end>selected.end)next.push({...n,id:n.id+'r',start:selected.end});}notes=next;saveNotes();paintAnnotations();getSelection()?.removeAllRanges();$g('annoFeedback').textContent='Marquages retirés sur la sélection.';};
$g('annoExport').onclick=()=>{const blob=new Blob([JSON.stringify({format:'garage-annotations-v1',notes},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='garage-marquages.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$g('annoFeedback').textContent='Export demandé au navigateur. Vérifiez que le fichier a été téléchargé.';};
$g('annoImport').onclick=()=>$g('annoFile').click();$g('annoFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const data=JSON.parse(await f.text());if(data.format!=='garage-annotations-v1'||!Array.isArray(data.notes))throw Error();const valid=data.notes.filter(n=>typeof n.key==='string'&&/^[bm]:[0-9:]+$/.test(n.key)&&typeof n.text==='string'&&n.text.length<100000&&Number.isInteger(n.start)&&Number.isInteger(n.end)&&n.start>=0&&n.end>n.start&&n.end<=n.text.length&&['highlight','underline'].includes(n.type)&&/^#[a-f0-9]{6}$/i.test(n.color));const dedup=new Set(notes.map(n=>JSON.stringify([n.key,n.start,n.end,n.type,n.color])));valid.forEach(n=>{const k=JSON.stringify([n.key,n.start,n.end,n.type,n.color]);if(!dedup.has(k)){notes.push(n);dedup.add(k);}});saveNotes();paintAnnotations();$g('annoFeedback').textContent=valid.length+' marquage(s) valide(s) lus ; doublons ignorés.';}catch(err){$g('annoFeedback').textContent='Fichier de marquages invalide ou trop volumineux.';}e.target.value='';};
let paintTimer;const observer=new MutationObserver(()=>{clearTimeout(paintTimer);paintTimer=setTimeout(paintAnnotations,100);});
function observe(){observer.observe($('bibleView'),{childList:true,subtree:true});observer.observe($('msgView'),{childList:true,subtree:true});}
function paintAnnotations(){observer.disconnect();document.querySelectorAll('.vt,.pt').forEach(p=>{p.querySelectorAll('.user-mark').forEach(m=>m.replaceWith(...m.childNodes));p.normalize();const text=plainText(p),list=notes.filter(n=>n.key===keyFor(p)&&n.text===text);if(!list.length)return;let offset=0;for(const node of textNodes(p)){const value=node.textContent,frag=document.createDocumentFragment();let i=0;while(i<value.length){const stylesAt=x=>{let h='',u='';list.forEach(n=>{if(x>=n.start&&x<n.end){if(n.type==='highlight')h=n.color;else u=n.color;}});return [h,u];};const [h,u]=stylesAt(offset+i);let j=i+1;while(j<value.length&&JSON.stringify(stylesAt(offset+j))===JSON.stringify([h,u]))j++;if(h||u){const mark=document.createElement('span');mark.className='user-mark';mark.textContent=value.slice(i,j);if(h)mark.style.backgroundColor=h;if(u){mark.style.textDecorationLine='underline';mark.style.textDecorationColor=u;mark.style.textDecorationThickness='3px';mark.style.textUnderlineOffset='4px';}frag.append(mark);}else frag.append(document.createTextNode(value.slice(i,j)));i=j;}offset+=value.length;node.replaceWith(frag);}});observe();}
observe();paintAnnotations();
const setting=document.createElement('button');setting.className='annotation-setting';setting.textContent='✎ Marquages · couleurs, export et import';setting.onclick=()=>{closeDrawer();toolbar.hidden=false;selected=null;updateStorageLabel();};$('drawer').append(setting);
