// Le guide se lance à la demande depuis le tableau ou le bouton Guide.
window.GarageFeatures={getSelectionState:()=>selected?{key:selected.key,start:selected.start,end:selected.end,text:selected.text}:null,getAnnotations:()=>JSON.parse(JSON.stringify(notes)),removeAnnotation:i=>{notes.splice(i,1);saveNotes();paintAnnotations();},replaceAnnotations:items=>{notes=items.filter(n=>typeof n.key==='string'&&/^[bm]:[0-9:]+$/.test(n.key)&&typeof n.text==='string'&&Number.isInteger(n.start)&&Number.isInteger(n.end)&&n.start>=0&&n.end>n.start&&n.end<=n.text.length&&['highlight','underline'].includes(n.type)&&/^#[a-f0-9]{6}$/i.test(n.color));saveNotes();paintAnnotations();},runSearch,showAnnotationGuide,paintAnnotations,matches,dateOf,getGlobalState:()=>({sources:[...selectedSources],periods:[...selectedPeriods],book:+$g('globalBook').value,parts:[...selectedParts],mode:currentMode(),sort,ascending,busy:globalBusy,total:resultTotal,page:resultPage,engine:engineMode,loadedZones:[...globalLoadedZones],elapsed,results:results.map(r=>({type:r.type,year:r.year,b:r.b,dg:r.dg,n:r.n}))})};
